//! Enum definitions: names and numbers from the C++ headers, string forms from
//! `src/common/enum_util.cpp` (generated by DuckDB's `scripts/generate_enum_util.py`).

use std::collections::{BTreeMap, BTreeSet};
use std::path::Path;

use serde::{Deserialize, Serialize};

use crate::Result;

/// One C++ `enum class`, as snapshotted into `specs/enums.json`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EnumDef {
    /// Header defining the enum, relative to `src/include`.
    pub header: String,
    /// Underlying C++ integer type (`uint8_t`, ...).
    pub underlying: String,
    /// Members in `enum_util.cpp` order (aliases excluded).
    pub members: Vec<EnumMember>,
}

/// One enum member with its value and the strings `EnumUtil` accepts (the first is
/// what `EnumUtil::ToChars` prints).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EnumMember {
    pub name: String,
    pub value: i64,
    pub strings: Vec<String>,
}

/// Extracts the string tables of `enum_util.cpp`: enum name → `[(member, string)]`.
fn parse_enum_util(text: &str) -> Result<BTreeMap<String, Vec<(String, String)>>> {
    const START: &str = "static constexpr StringUtil::EnumStringLiteral values[] {";
    const CAST: &str = "static_cast<uint32_t>(";
    let mut tables: BTreeMap<String, Vec<(String, String)>> = BTreeMap::new();
    let mut rest = text;
    while let Some(start) = rest.find(START) {
        rest = &rest[start + START.len()..];
        let end = rest.find("};").ok_or("enum_util.cpp: unterminated table")?;
        let body = &rest[..end];
        let mut enum_name = None;
        let mut entries = Vec::new();
        for line in body.lines() {
            let Some(cast) = line.find(CAST) else { continue };
            let after = &line[cast + CAST.len()..];
            let close = after.find(')').ok_or("enum_util.cpp: bad cast")?;
            let qualified = &after[..close];
            let (name, member) = qualified
                .rsplit_once("::")
                .ok_or("enum_util.cpp: unqualified member")?;
            let quote = after.find('"').ok_or("enum_util.cpp: missing string")?;
            let string_end = after.rfind('"').ok_or("enum_util.cpp: missing string end")?;
            let string = after[quote + 1..string_end]
                .replace("\\\"", "\"")
                .replace("\\\\", "\\");
            enum_name = Some(name.to_owned());
            entries.push((member.to_owned(), string));
        }
        if let Some(name) = enum_name {
            tables.insert(name, entries);
        }
        rest = &rest[end..];
    }
    Ok(tables)
}

/// A raw `enum class` from a header: underlying type and `(member, value expression)`.
struct HeaderEnum {
    header: String,
    underlying: String,
    members: Vec<(String, Option<String>)>,
}

fn strip_comments(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '/' && chars.peek() == Some(&'/') {
            for c in chars.by_ref() {
                if c == '\n' {
                    out.push('\n');
                    break;
                }
            }
        } else if c == '/' && chars.peek() == Some(&'*') {
            chars.next();
            let mut previous = ' ';
            for c in chars.by_ref() {
                if previous == '*' && c == '/' {
                    break;
                }
                previous = c;
            }
            out.push(' ');
        } else {
            out.push(c);
        }
    }
    out
}

fn parse_header_enums(header: &str, text: &str, out: &mut BTreeMap<String, Vec<HeaderEnum>>) {
    let text = strip_comments(text);
    let mut rest = text.as_str();
    while let Some(pos) = rest.find("enum class ") {
        rest = &rest[pos + "enum class ".len()..];
        let Some(brace) = rest.find('{') else { break };
        let Some(semicolon) = rest.find(';') else { break };
        if semicolon < brace {
            // forward declaration
            continue;
        }
        let head = rest[..brace].trim();
        let (name, underlying) = match head.split_once(':') {
            Some((name, ty)) => (name.trim(), ty.trim()),
            None => (head, "int"),
        };
        let Some(close) = rest[brace..].find('}') else {
            break;
        };
        let body = &rest[brace + 1..brace + close];
        let members = body
            .split(',')
            .map(str::trim)
            .filter(|item| !item.is_empty())
            .map(|item| match item.split_once('=') {
                Some((member, value)) => (member.trim().to_owned(), Some(value.trim().to_owned())),
                None => (item.to_owned(), None),
            })
            .collect();
        out.entry(name.to_owned()).or_default().push(HeaderEnum {
            header: header.to_owned(),
            underlying: underlying.to_owned(),
            members,
        });
        rest = &rest[brace + close..];
    }
}

fn collect_headers(dir: &Path, root: &Path, out: &mut BTreeMap<String, Vec<HeaderEnum>>) -> Result<()> {
    let mut entries: Vec<_> = std::fs::read_dir(dir)?.collect::<std::io::Result<_>>()?;
    entries.sort_by_key(std::fs::DirEntry::path);
    for entry in entries {
        let path = entry.path();
        if path.is_dir() {
            collect_headers(&path, root, out)?;
        } else if path.extension().is_some_and(|ext| ext == "hpp") {
            let text = std::fs::read_to_string(&path)?;
            if text.contains("enum class ") {
                let relative = path
                    .strip_prefix(root)
                    .unwrap_or(&path)
                    .to_string_lossy()
                    .into_owned();
                parse_header_enums(&relative, &text, out);
            }
        }
    }
    Ok(())
}

/// Evaluates an enumerator initializer: integer and character literals, references to
/// earlier members, unary minus, `<<` and `|`.
fn evaluate(expr: &str, known: &BTreeMap<String, i64>) -> Option<i64> {
    let expr = expr.trim();
    if let Some((left, right)) = expr.split_once('|') {
        return Some(evaluate(left, known)? | evaluate(right, known)?);
    }
    if let Some((left, right)) = expr.split_once("<<") {
        return Some(evaluate(left, known)? << evaluate(right, known)?);
    }
    if let Some(inner) = expr.strip_prefix('(').and_then(|e| e.strip_suffix(')')) {
        return evaluate(inner, known);
    }
    if let Some(negated) = expr.strip_prefix('-') {
        return evaluate(negated, known).map(|v| -v);
    }
    if let Some(ch) = expr.strip_prefix('\'').and_then(|e| e.strip_suffix('\'')) {
        let mut chars = ch.chars();
        let value = chars.next()?;
        return chars.next().is_none().then_some(i64::from(u32::from(value)));
    }
    let digits = expr.trim_end_matches(['u', 'U', 'l', 'L']);
    if let Some(hex) = digits.strip_prefix("0x").or_else(|| digits.strip_prefix("0X")) {
        return i64::from_str_radix(hex, 16).ok();
    }
    if let Ok(value) = digits.parse() {
        return Some(value);
    }
    let name = expr.rsplit("::").next().unwrap_or(expr);
    known.get(name).copied()
}

/// Resolves the member values of a header enum.
fn resolve_values(def: &HeaderEnum) -> Result<BTreeMap<String, i64>> {
    let mut values = BTreeMap::new();
    let mut next = 0i64;
    for (member, init) in &def.members {
        let value = match init {
            Some(expr) => evaluate(expr, &values)
                .ok_or_else(|| format!("{}: cannot evaluate '{member} = {expr}'", def.header))?,
            None => next,
        };
        values.insert(member.clone(), value);
        next = value + 1;
    }
    Ok(values)
}

/// Builds definitions for `wanted` enums from a DuckDB source tree.
pub fn import(duckdb: &Path, wanted: &BTreeSet<String>) -> Result<BTreeMap<String, EnumDef>> {
    let enum_util = std::fs::read_to_string(duckdb.join("src/common/enum_util.cpp"))?;
    let tables = parse_enum_util(&enum_util)?;
    let include = duckdb.join("src/include");
    let mut headers = BTreeMap::new();
    collect_headers(&include, &include, &mut headers)?;

    let mut result = BTreeMap::new();
    for name in wanted {
        let Some(table) = tables.get(name) else {
            continue;
        };
        let candidates = headers
            .get(name)
            .ok_or_else(|| format!("enum {name} is in enum_util.cpp but not in any header"))?;
        // Pick the header definition that declares every member of the string table.
        let def = candidates
            .iter()
            .find(|def| table.iter().all(|(m, _)| def.members.iter().any(|(n, _)| n == m)))
            .ok_or_else(|| format!("no header definition of {name} matches enum_util.cpp"))?;
        let values = resolve_values(def)?;
        let mut members: Vec<EnumMember> = Vec::new();
        for (member, string) in table {
            if let Some(existing) = members.iter_mut().find(|m| &m.name == member) {
                existing.strings.push(string.clone());
                continue;
            }
            let value = *values
                .get(member)
                .ok_or_else(|| format!("{name}::{member} has no value"))?;
            members.push(EnumMember {
                name: member.clone(),
                value,
                strings: vec![string.clone()],
            });
        }
        result.insert(
            name.clone(),
            EnumDef {
                header: def.header.clone(),
                underlying: def.underlying.clone(),
                members,
            },
        );
    }
    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_tables_and_values() {
        let util = r#"
const StringUtil::EnumStringLiteral *GetOrderTypeValues() {
	static constexpr StringUtil::EnumStringLiteral values[] {
		{ static_cast<uint32_t>(OrderType::INVALID), "INVALID" },
		{ static_cast<uint32_t>(OrderType::ORDER_DEFAULT), "ORDER_DEFAULT" },
		{ static_cast<uint32_t>(OrderType::ORDER_DEFAULT), "DEFAULT" }
	};
	return values;
}"#;
        let tables = parse_enum_util(util).unwrap();
        assert_eq!(tables["OrderType"].len(), 3);

        let mut headers = BTreeMap::new();
        parse_header_enums(
            "x.hpp",
            "enum class Foo : uint8_t { A = 1, // c\n B, C = A, D = 1 << 4, E = 'x' };",
            &mut headers,
        );
        let values = resolve_values(&headers["Foo"][0]).unwrap();
        assert_eq!(values["B"], 2);
        assert_eq!(values["C"], 1);
        assert_eq!(values["D"], 16);
        assert_eq!(values["E"], 120);
    }
}
